/**
 * Delete any character in a given String.
 * @param inString the original String
 * @param charsToDelete a set of characters to delete. E.g. "az\n" will delete 'a's, 'z's and new lines.
 * @return the resulting String
 */
public static String deleteAny(String inString, String charsToDelete) {
    if (inString == null || charsToDelete == null) {
        return inString;   // nothing to delete
    }

    // Build a lookup table for the characters to delete
    // Using a boolean array for ASCII (0‑255) is fast; for full Unicode we can use a HashSet
    boolean[] deleteTable = new boolean[256];
    for (int i = 0; i < charsToDelete.length(); i++) {
        char c = charsToDelete.charAt(i);
        if (c < 256) {
            deleteTable[c] = true;
        }
    }

    StringBuilder sb = new StringBuilder(inString.length());
    for (int i = 0; i < inString.length(); i++) {
        char c = inString.charAt(i);
        if (c < 256) {
            if (!deleteTable[c]) {
                sb.append(c);
            }
        } else {
            // For characters outside the 0‑255 range, fall back to a simple check
            if (charsToDelete.indexOf(c) == -1) {
                sb.append(c);
            }
        }
    }
    return sb.toString();
}
