/**
 * Returns {@code true} if the given string matches the given substring at the given index,
 * {@code false} otherwise.
 *
 * @param str       the original string (or {@link StringBuilder})
 * @param index     the index in the original string to start matching against
 * @param substring the substring to match at the given index
 * @return {@code true} if the given string matches the given substring at the given index,
 *         {@code false} otherwise.
 */
public static boolean substringMatch(CharSequence str, int index, CharSequence substring) {
    // Quick checks for null references
    if (str == null || substring == null) {
        return false;
    }

    int strLen = str.length();
    int subLen = substring.length();

    // If the index is out of bounds or the substring would extend beyond the end of str,
    // the match cannot succeed.
    if (index < 0 || index + subLen > strLen) {
        return false;
    }

    // Compare character by character
    for (int i = 0; i < subLen; i++) {
        if (str.charAt(index + i) != substring.charAt(i)) {
            return false;
        }
    }

    return true;
}
